import{_ as o,c as r,o as s,ah as e}from"./chunks/framework.RCw5T9E9.js";const c=JSON.parse('{"title":"Избранное","description":"","frontmatter":{"title":"Избранное"},"headers":[],"relativePath":"ru/store/favorite.md","filePath":"ru/store/favorite.md"}'),n={name:"ru/store/favorite.md"};function a(i,t,g,l,d,p){return s(),r("div",null,[...t[0]||(t[0]=[e('<h1 id="избранное-pinia-store" tabindex="-1">Избранное (Pinia Store) <a class="header-anchor" href="#избранное-pinia-store" aria-label="Permalink to &quot;Избранное (Pinia Store)&quot;">​</a></h1><p><strong>Избранные сторы</strong> — это сохраняемый список <strong>Pinia store</strong>, который помогает быстрее ориентироваться во вкладке <strong>Stores</strong>: отмеченные строки поднимаются <strong>в начало списка</strong>, рядом отображается <strong>звезда</strong>, а в шапке доступен счётчик найденных избранных среди текущих результатов.</p><p>Общее описание вкладки Store: <a href="/qa-tools/docs/ru/store/general.html">Основные возможности</a>. Избранное <strong>компонентов Vue</strong> (вкладка Props) — отдельный механизм: <a href="/qa-tools/docs/ru/props/favorite.html">Избранное (Props)</a>.</p><hr><h2 id="где-добавить-и-убрать" tabindex="-1">Где добавить и убрать <a class="header-anchor" href="#где-добавить-и-убрать" aria-label="Permalink to &quot;Где добавить и убрать&quot;">​</a></h2><p>Добавить store в избранное можно несколькими способами.</p><ul><li><strong>В карточке store</strong> — в заголовке доступна кнопка <strong>звезды</strong>, которая включает или снимает признак избранного для текущего store.</li><li><strong>Через контекстное меню строки в таблице Stores</strong> — команда добавления или удаления доступна среди действий над выбранной строкой.</li><li><strong>В таблице Stores</strong> — быстрый клик по области <strong>звезды</strong> у строки также переключает избранное, даже если иконка ещё не отображается постоянно.</li><li><strong>В Options</strong> — секция <strong>Favorite Stores</strong> в блоке <strong>Pinia Store</strong>. Список и карточка деталей описаны ниже.</li></ul><p>Настройки сохраняются в общем хранилище инспектора вместе с остальными параметрами.</p><hr><h2 id="точное-имя-и-маски" tabindex="-1">Точное имя и маски <a class="header-anchor" href="#точное-имя-и-маски" aria-label="Permalink to &quot;Точное имя и маски&quot;">​</a></h2><p>Каждая запись в списке избранного задаёт <strong>шаблон имени store</strong>.</p><ul><li>Если запись <strong>не содержит</strong> символ <strong><code>*</code></strong>, совпадение <strong>точное</strong> и учитывает регистр: звезда только у store с этим именем.</li><li><strong><code>*</code></strong> — любая последовательность, и шаблон должен совпасть со всем именем. Например, <strong>use*Store</strong> совпадает с <strong>useUserStore</strong> и <strong>useAuthStore</strong>. Регистр значим.</li></ul><p>При снятии избранного со строки таблицы удаляются все записи, которые считаются совпадающими для этого store: как точные, так и подходящие по маске.</p><p>В форме ручного ввода в <strong>Options</strong> поддержка wildcard сохраняется в том же формате.</p><hr><h2 id="что-именно-сохраняется" tabindex="-1">Что именно сохраняется <a class="header-anchor" href="#что-именно-сохраняется" aria-label="Permalink to &quot;Что именно сохраняется&quot;">​</a></h2><p>Для каждой записи инспектор хранит:</p><ul><li><strong>id</strong> и <strong>name</strong>: при отметке строки оба равны отображаемому имени (маска, введённая в Options, хранится в этих строках);</li><li><strong>storeId</strong> экземпляра в момент отметки. Звезда это поле не использует;</li><li><strong>время добавления</strong>.</li></ul><p>Это позволяет повторно применять список после обновления дерева store.</p><hr><h2 id="как-выполняется-сопоставление" tabindex="-1">Как выполняется сопоставление <a class="header-anchor" href="#как-выполняется-сопоставление" aria-label="Permalink to &quot;Как выполняется сопоставление&quot;">​</a></h2><p>Отображаемое имя (<code>baseId</code>) сравнивается с <strong>id</strong> и <strong>name</strong> каждой записи. Точное равенство или шаблон с <code>*</code> в любом из этих полей ставит звезду. Сравнение учитывает регистр. Сохранённый <strong>storeId</strong> в совпадении не участвует.</p><p>Если несколько store подходят под одну маску, звезда есть у каждой такой строки.</p><hr><h2 id="сортировка-и-счетчик" tabindex="-1">Сортировка и счётчик <a class="header-anchor" href="#сортировка-и-счетчик" aria-label="Permalink to &quot;Сортировка и счётчик&quot;">​</a></h2><p>Таблица держит избранные строки сверху.</p><p>Бейдж виден всегда. Если ничего не сохранено, на нём <code>0</code>, иначе видимые избранные / всего сохранённых. Жёлтый, когда хотя бы одна видимая строка в избранном.</p><p>Клик по бейджу открывает <strong>Options → Pinia Store → Favorite Stores</strong>.</p><hr><h2 id="favorite-stores-в-options" tabindex="-1">Favorite Stores в Options <a class="header-anchor" href="#favorite-stores-в-options" aria-label="Permalink to &quot;Favorite Stores в Options&quot;">​</a></h2><p>Блок второй на <strong>Options → Pinia Store</strong>. Подсказка поля: <strong>Store name (supports wildcards: <em>Store</em>)</strong>. <strong>Add</strong> или <strong>Enter</strong> обрезает пробелы и добавляет строку, у которой <strong>id</strong> и <strong>name</strong> равны этой строке. Поля <strong>storeId</strong> нет. Пустое значение: <strong>Name cannot be empty</strong>. Тот же <strong>id</strong> или <strong>name</strong> уже в списке: <strong>This store is already in favorites</strong>. Проверка — точная строка, поэтому <code>Foo</code> и <code>foo</code> — две записи, а маска не считается дубликатом имени, которое она накрыла бы.</p><p>Строки остаются в порядке сохранения.</p><table tabindex="0"><thead><tr><th>Колонка</th><th>Что показывает</th></tr></thead><tbody><tr><td><strong>Store Name</strong></td><td>Сохранённое имя.</td></tr><tr><td><strong>Added</strong></td><td>Только локальная дата.</td></tr></tbody></table><p>Меню строки (правый клик или <strong>⋮</strong>): <strong>Edit</strong> и <strong>Delete</strong>. <strong>Delete</strong> удаляет все записи с этим <strong>id</strong>. Другие шаблоны, которые лишь совпадают с тем же store, оно не снимает. Пустая таблица: <em>No favorite stores</em>.</p><p>Клик открывает <strong>Favorite Store Details</strong>: <strong>Store Name</strong> и <strong>Added</strong> — локальные дата и время. <strong>Edit</strong> в меню строки открывает карточку сразу в режиме правки. Иконка <strong>Edit</strong> в шапке открытой карточки делает то же. Подсказка поля: <strong>Store name</strong>. <strong>Enter</strong> или <strong>Save</strong> записывает обрезанный текст и в <strong>id</strong>, и в <strong>name</strong> и сохраняет <strong>storeId</strong>, если он у строки был. <strong>Save</strong> недоступна, пока поле пустое, и не проверяет, есть ли уже строка с таким именем. <strong>Cancel</strong> выходит из правки и оставляет карточку. <strong>Назад</strong> или <strong>Escape</strong> закрывают карточку, в том числе во время правки.</p><p>Если ничего не выбрано, панель пишет <em>Select an item to see details</em>. Если запись удалили при открытой карточке, она пишет <em>Item no longer exists</em>. Ниже <strong>1000</strong> px карточка закрывает список настроек, пока её не закроют.</p><p>Карточка не выбирает этот store на вкладке Stores.</p><hr><h2 id="практические-советы" tabindex="-1">Практические советы <a class="header-anchor" href="#практические-советы" aria-label="Permalink to &quot;Практические советы&quot;">​</a></h2><ul><li>Удобно добавлять в избранное <strong>основные store проекта</strong>: пользователь, настройки, состояние интерфейса.</li><li><strong>Маски</strong> полезны в проектах с однотипным именованием, но слишком широкий шаблон может выделить лишние строки.</li><li>Избранное <strong>не влияет</strong> на выполнение Pinia в приложении и хранится локально в настройках инспектора.</li></ul><hr><h2 id="см-также" tabindex="-1">См. также <a class="header-anchor" href="#см-также" aria-label="Permalink to &quot;См. также&quot;">​</a></h2><ul><li><a href="/qa-tools/docs/ru/store/general.html">Основные возможности Store</a></li><li><a href="/qa-tools/docs/ru/props/favorite.html">Избранное (Props)</a></li><li><a href="/qa-tools/docs/ru/options/customize.html">Персонализация / настройки</a></li></ul>',43)])])}const u=o(n,[["render",a]]);export{c as __pageData,u as default};
